    {
        var_idReaOco: varIATAUser & "-" & LookUp(
            tbl_Modulos,
            Titulo = "Ocorrências REA",
            Identificador
        ) & "-" & Value(
            First(
                SortByColumns(
                    tbl_ReaOcorrencias,
                    "ID",
                    SortOrder.Descending
                )
            ).ID
        ) + 1,
        var_criticidade: ComboboxCanvasAlterarCriticidade.Selected.Value
