        "BAIXO",
        Filter(
            tbl_userNotify,
            ID_FK_MODULO = 44 And CRITICIDADE = "BAIXO" And Aeroporto = varAeroUser
        ),
        "MÉDIO",
        Filter(
            tbl_userNotify,
            ID_FK_MODULO = 44 And CRITICIDADE = "BAIXO" And Aeroporto = varAeroUser Or CRITICIDADE = "MÉDIO" And Aeroporto = varAeroUser Or Bloco = varBlocoUser And NIVEL_ACIONAMENTO.Value = "BLOCO"
        ),
        "CRÍTICO",
        Filter(
            tbl_userNotify,
            ID_FK_MODULO = 44 And CRITICIDADE = "BAIXO" And Aeroporto = varAeroUser Or CRITICIDADE = "MÉDIO" And Aeroporto = varAeroUser Or Bloco = varBlocoUser And NIVEL_ACIONAMENTO.Value = "BLOCO" Or CRITICIDADE = "CRÍTICO"
